"""Ask local Code Author for two exact register-slot edits; retain raw output."""
import json,fcntl,sys,subprocess
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'scripts'));import lmstudio,sdk_thinking_override_probe
sdk_thinking_override_probe.install();prior=json.loads((ROOT/'verification/tile-task-local-author-current.json').read_text());folder=Path(prior['directory']);cases=(folder/'model-cases.cfrag').read_text();out=ROOT/'verification/BIWN-tile-task-local-author'/datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S.%fZ');out.mkdir(parents=True);print(out,flush=True)
prompt='The draft passed16disabled-mode native checks then failed tile12 RAM preservation. Two ADDA instructions wrongly mutateD7(slot7) instead ofA7(slot15). Return ONLY JSONarray of exactlytwoobjects with old,new strings. Change "s.cpu.registers[7] -= 28u;" to use index15, and "s.cpu.registers[7] += 28u;" to use index15. LeaveMOVEM D7slot7 unchanged. No other edits. This changes sourceprivate stack allocation and its matching release; bank(&s) already follows both lines.'
protocol={'role':'local Code Author targetedrepair','model':'advertising-scholar','system':'Return exact JSONedits requested. Source task ABI defines A7slot15, D7slot7. Do not claim verification.','user':prompt,'repair_of':str(folder/'protocol.json'),'coordinator_prefix':prior['coordinator_prefix'],'coordinator_suffix':prior['coordinator_suffix'],'model_authorship':'13model-generatedswitchcases with two model-issued register-slot corrections; coordinator scaffolding/test guidance.','new_training':False,'directory':str(out)}
with(ROOT/'runs/.inference.lock').open('w')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX);chat=lmstudio.Chat(protocol['system']);chat.add_user_message(prompt);response=lmstudio.llm('advertising-scholar').respond(chat,config={'temperature':0.1,'maxTokens':512,'raw':{'fields':[{'key':'llm.prediction.reasoning.enableThinking','value':False},{'key':'ext.virtualModel.customField.enableThinking','value':False},{'key':'ext.virtualModel.customField.preserveThinking','value':False}]}});raw=response.content;(out/'raw-response.txt').write_text(raw);text=raw.strip();text=text.split('```json',1)[1].split('```',1)[0]if'```json'in text else text;edits=json.loads(text);assert len(edits)==2 and {e['old']for e in edits}=={'s.cpu.registers[7] -= 28u;','s.cpu.registers[7] += 28u;'}
 for e in edits:assert e['new']==e['old'].replace('[7]','[15]') and cases.count(e['old'])==1;cases=cases.replace(e['old'],e['new'])
 (out/'model-cases.cfrag').write_text(cases);(out/'candidate.c').write_text(prior['coordinator_prefix']+cases+prior['coordinator_suffix']);protocol.update(status='targeted_model_correction_returned_unverified',raw_response=raw,model_edits=edits);(out/'protocol.json').write_text(json.dumps(protocol,indent=2)+'\n');(ROOT/'verification/tile-task-local-author-current.json').write_text(json.dumps(protocol,indent=2)+'\n');print(protocol['status'],flush=True)
